import{_ as n,l as s,o as e,c as o,v as r,p as l,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"行波进位对照","description":"","frontmatter":{"title":"行波进位对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ripple-adder.md","filePath":"cs/ripple-adder.md","lastUpdated":1789023840000}'),_={name:"cs/ripple-adder.md"};function A(h,a,E,m,C,u){const i=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="行波进位对照" tabindex="-1">行波进位对照 <a class="header-anchor" href="#行波进位对照" aria-label="Permalink to &quot;行波进位对照&quot;">​</a></h1><div class="epigraph"><p>超前进位把进位写成 $g,p$ 的与或；行波则老老实实让 $c_{i+1}$ 等 $c_i$，功能相同，关键路径差一个 $\\Theta(n)$。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/adder-cla">加法器与超前进位</a>已经给出全加器与 \\(g,p\\)。本课不重推 \\(c_{i+1}=g_i+p_i c_i\\)，也不从补码溢出再证。缺口是：CLA 为什么值得画，必须把<strong>行波加法器</strong>当作对照物钉死——面积小、接线短、延迟随位宽线性涨。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 位 RCA：第 \\(i\\) 位全加器的进位出接到第 \\(i+1\\) 位进位入。关键路径穿过每一位的进位逻辑，<a href="/cs/critical-path">关键路径</a>上 \\(t_{pd}\\approx n\\cdot t_{\\mathrm{carry}}\\)。缺口不是新的加法语义，而是量这一条链：字长从 8 到 64，同一结构会从「可接受」变成单周期的瓶颈。</p><p>本课只钉 RCA 的结构与延迟阶。进位选择、乘法阵列是后课。</p><h3 id="行波不是「算错了的-cla」" tabindex="-1">行波不是「算错了的 CLA」 <a class="header-anchor" href="#行波不是「算错了的-cla」" aria-label="Permalink to &quot;行波不是「算错了的 CLA」&quot;">​</a></h3><p>每一位的和、进位布尔式与用 CLA 展开后的值相同。差别只在中间进位是否提前算完。把 RCA 当成过时算法、CLA 当成另一种算术，会把后课进位选择说成第三种加法定义。</p><p><span class="marginnote">Harris 先画 RCA 再引入 4 位 CLA 积木。Patterson/Hennessy 用加法器延迟说明为何 ALU 是关键路径候选。本课不把流水线拆加引进来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>位片：\\((s_i,c_{i+1})=\\mathrm{FA}(a_i,b_i,c_i)\\)，\\(c_0\\) 为加/减控制。画时序：最坏是 \\(c_0\\) 传到 \\(c_n\\) 再出 \\(s_{n-1}\\)。面积：\\(\\Theta(n)\\) 个全加器，无额外 \\(g,p\\) 树。</p>',11)),(e(),l(c,null,{default:t(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FA%5B%221%20%E4%BD%8D%E5%85%A8%E5%8A%A0%E5%99%A8%22%5D%20--%3E%20RCA%5B%22%E8%BF%9B%E4%BD%8D%E9%93%BE%E4%B8%B2%20n%20%E4%BD%8D%22%5D%0A%20%20RCA%20--%3E%20LIN%5B%22%E5%85%B3%E9%94%AE%E8%B7%AF%E5%BE%84%20%CE%98(n)%22%5D%0A%20%20LIN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%BF%9B%E4%BD%8D%E9%80%89%E6%8B%A9%E6%8A%98%E4%B8%AD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 ALU 可以先用 RCA 把功能跑通，再用 CLA 换延迟。教材单周期常在图上画一个 ALU 框，框内是哪一种加法器只改 \\(T\\)，不改控制表。减法仍是 \\(\\bar B\\) 加 \\(c_0=1\\)，与上一课相同，只是进位走链。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲并行前缀加法器（Kogge–Stone 等）的布线拥塞。不把异步进位完成信号当默认同步设计。</p><p>后课默认：RCA 功能正确、延迟线性；CLA 用面积换深度。下一课在两者之间再放一种分块并行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RCA：进位位片串联，关键路径随 \\(n\\) 线性。</li><li>与 CLA 算术等价，只比延迟与面积。</li><li>加减接线不变，仍用 \\(c_0\\)。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const D=n(_,[["render",A]]);export{f as __pageData,D as default};
